(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.025-t*0.4)*8+Math.cos((y+wy1)*0.02+t*0.3)*6;
  const wy2 = Math.cos((y+wy1)*0.025+t*0.35)*8+Math.sin((x+wx1)*0.022-t*0.45)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*55,0.085,1.8],
    [200+Math.sin(t*0.7+5)*90,220+Math.cos(t*0.3+3)*40,0.095,2.4]
  ];
  let aS=0,iS=0,bS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    bS+=Math.cos(d*f*0.5-t*sp*0.4+3.0);
  }
  const act=aS/9,inh=iS/9,bif=bS/9;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin(sx*0.08-sy*0.06+t*1.5)+Math.cos(sx*0.06+sy*0.09-t*1.3))/2;
  const bg3=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg=bg1+bg2*0.5+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=(Math.sin(dist*0.08+ang*2+t*0.9)+Math.cos(dist*0.06-ang*5+t*1.1))*0.25;
  const rd2=Math.tanh((Math.sin(sx*0.12+act*2)*Math.cos(sy*0.1+inh*2)+Math.sin((sx-sy)*0.08+t*0.7)*0.6)*1.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+sy*0.25+bif*3)*Math.cos(sx*0.2-sy*0.3+t*1.5)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+sp1+sp2+bif*0.2)*2.2);
  const blend=reaction*0.55+rd2*0.2+cell*0.15+micro*0.1,v=blend*0.5+0.5;
  const pal=[[5,12,55],[10,45,95],[15,85,120],[20,135,140],[45,175,145],[120,195,120],[200,195,75],[220,165,60],[200,110,55],[160,60,55],[100,30,55],[50,15,50],[5,12,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.7?1.2:Math.abs(reaction)>0.5?1.05:1.0;
  const shimmer=1.0+Math.sin(dist*0.1+t*3)*0.03;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*shimmer)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*shimmer)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*shimmer)|0
  ];
}
